'use strict';
const $=id=>document.getElementById(id),fmt=n=>Math.round(n).toLocaleString('zh-HK');
let frequencyPeriod='month',duration=2,shown=false,timer,announceTimer,estimateTimer;const drafts=new Map();let previousWho='parent';
const defaults={parent:[60,18],grand:[75,0],partner:[30,25]};
const dots=Array.from({length:100},()=>{const d=document.createElement('span');d.className='dot';$('dots').append(d);return d;});
function read(){const who=$('who').value;const s={who,frequency:Number($('frequency-count').value)*periodSettings[frequencyPeriod].factor,duration};for(const k of ['age','their','milestone','life','home','ownLife','extra','extraHours'])s[k]=Number($(k).value);return s;}
const relationNames={parent:'爸爸／媽媽',grand:'祖父母／外祖父母',partner:'伴侶'};
const periodSettings={week:{label:'每星期',factor:52,max:7},month:{label:'每個月',factor:12,max:31},year:{label:'每年',factor:1,max:365}};
function frequencyOptions(who){return who==='partner'?['week','month']:['week','month','year'];}
function configureFrequency(who){const group=$('frequency'),period=periodSettings[frequencyPeriod];$('frequency-count-control').hidden=false;$('frequency-count').disabled=false;$('frequency-count').max=period.max;$('frequency-count-label').textContent=period.label+'相處幾次？';if(group.dataset.mode!==who){group.replaceChildren(...frequencyOptions(who).map(value=>{const button=document.createElement('button');button.type='button';button.dataset.period=value;button.textContent=periodSettings[value].label;return button;}));group.dataset.mode=who;}for(const button of group.querySelectorAll('button')){const selected=button.dataset.period===frequencyPeriod;button.classList.toggle('active',selected);button.setAttribute('aria-pressed',String(selected));}}
function renderSettings(s){const frequencyText=`${periodSettings[frequencyPeriod].label}${$('frequency-count').value}次`;const milestone=s.who==='parent'?(s.milestone>s.age?`預計${s.milestone}歲搬出`:`${s.milestone}歲起分開住`):s.who==='grand'?(s.milestone===0?'從未同住':`同住至${s.milestone}歲`):`${s.milestone}歲認識`;const values=[`你${s.age}歲・對方${s.their}歲`,milestone,frequencyText,`每次${s.duration}小時`,`假設對方${s.life}歲・你${s.ownLife}歲`];if(['parent','grand'].includes(s.who))values.push(`同住每日${s.home}小時`);$('chosen-settings').replaceChildren(...values.map(text=>{const chip=document.createElement('span');chip.setAttribute('role','listitem');chip.textContent=text;return chip;}));}
function validate(s){if(!frequencyOptions(s.who).includes(frequencyPeriod)||$('frequency-count').value===''||!$('frequency-count').checkValidity()||![1,2,4,8].includes(s.duration))return '請選擇有效的見面頻率及每次相處時間。';for(const k of ['age','their','milestone','life','home','ownLife','extra','extraHours']){const el=$(k);if(el.value===''||!el.checkValidity())return '請填入有效嘅年齡或時數。';}if(s.life<s.their||s.ownLife<s.age)return '假設年齡上限唔可以細過而家嘅年齡。';if(s.who==='partner'&&(s.milestone>s.age||s.age-s.milestone>s.their))return '認識年齡需要介乎你出生至而家，而且對方當時已經出生。';if(s.who==='grand'&&s.milestone>s.age)return '同住至幾多歲，請填不大於你而家嘅年齡。';return '';}
function percentText(n){if(n===null)return '—';if(n>99&&n<100)return '>99';if(n>0&&n<1)return '<1';return Math.round(n);}
function animateNumber(el,to){const old=Number(el.dataset.value);el.dataset.value=to;cancelAnimationFrame(el._frame);if(!shown||!Number.isFinite(old)||matchMedia('(prefers-reduced-motion: reduce)').matches){el.textContent=fmt(to);return;}const start=performance.now();function tick(now){const p=Math.min(1,(now-start)/420);el.textContent=fmt(old+(to-old)*(1-(1-p)**3));if(p<1)el._frame=requestAnimationFrame(tick);}el._frame=requestAnimationFrame(tick);}
function choices(){const s=read();configureFrequency(s.who);const family=['parent','grand'].includes(s.who);$('milestone-label').textContent=s.who==='parent'?'你幾多歲搬咗／預計搬出去住？':s.who==='grand'?'你同佢一齊住到幾多歲？':'你幾多歲認識佢？';$('milestone-note').textContent=s.who==='parent'?'仍然同住？可填預計搬出嘅年齡。':s.who==='grand'?'從未同住請填 0。仍同住可填目前年齡。':'';$('milestone-note').hidden=!family;$('frequency-label').textContent='你哋平時大約幾耐一起相處一次？';$('home-control').hidden=!family;for(const el of document.querySelectorAll('.number-control input')){const label=document.querySelector(`label[for="${el.id}"]`);const buttons=el.parentElement.querySelectorAll('.stepper');if(buttons.length===2){buttons[0].setAttribute('aria-label','減少'+label.textContent);buttons[1].setAttribute('aria-label','增加'+label.textContent);}}}
function update(reason){choices();const s=read(),error=validate(s);$('error').textContent=error;
if(!error){const r=TimeModel.calculate(s);$('together-label').textContent=`和你的${relationNames[s.who]}還可以一起度過`;renderSettings(s);$('adjustment-limit').hidden=!r.capped;animateNumber($('remaining-days'),r.ahead/24);const remainingPercent=r.total?r.ahead/r.total*100:null;$('percent').textContent=percentText(remainingPercent);animateNumber($('remaining-hours'),r.ahead);clearTimeout(announceTimer);if(shown)announceTimer=setTimeout(()=>{$('scenario-announcement').textContent=`往後相處的時間約 ${fmt(r.ahead)} 小時，佔估算總相處時間約 ${percentText(remainingPercent)}%。`;},500);animateNumber($('past'),r.past);animateNumber($('ahead'),r.ahead);$('gain-legend').hidden=!(r.gain>0);for(let i=0;i<100;i++){const p=r.total?Math.max(0,Math.min(1,r.past/r.total*100-i))*100:0,b=r.total?Math.max(0,Math.min(1,(r.past+r.baseline)/r.total*100-i))*100:0;dots[i].style.background=r.total?`linear-gradient(90deg,#756186 ${p}%,#e4dbe9 ${p}%,#e4dbe9 ${b}%,#a7b99a ${b}%)`:'#e4dbe9';dots[i].classList.toggle('has-gain',r.gain>0&&b<100);}$('dots').setAttribute('aria-label',r.total?`往後相處的時間約佔 ${percentText(remainingPercent)}%；估計 ${fmt(r.ahead)} 小時。${r.gain>0?'當中新增 '+fmt(r.gain)+' 小時。':''}`:'暫未有相處時間可比較。');}
}
function toggleResult(on){clearTimeout(estimateTimer);$('time-loading').hidden=true;shown=on;$('form-panel').hidden=on;$('form-intro').hidden=on;$('result-panel').hidden=!on;window.scrollTo({top:0,behavior:'instant'});if(on){const panel=$('result-panel');panel.classList.remove('result-revealing');void panel.offsetWidth;panel.classList.add('result-revealing');panel.focus({preventScroll:true});}else{document.querySelector('[data-who].active').focus({preventScroll:true});}}
for(const group of ['frequency','duration'])$(group).addEventListener('click',event=>{const b=event.target.closest('button');if(!b)return;if(group==='frequency'&&b.dataset.period){frequencyPeriod=b.dataset.period;const count=$('frequency-count');count.max=periodSettings[frequencyPeriod].max;count.value=Math.max(1,Math.min(Number(count.max),Number(count.value)||1));}else if(group==='duration'&&b.dataset.value!==undefined)duration=Number(b.dataset.value);else return;for(const x of $(group).querySelectorAll('button')){x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b));}update(group);});
for(const el of document.querySelectorAll('input'))el.addEventListener('input',()=>{update(el.id);});
for(const el of document.querySelectorAll('input[type=number]')){const wrap=document.createElement('div');wrap.className='number-control';el.before(wrap);const label=document.querySelector(`label[for="${el.id}"]`);for(const direction of [-1,1]){const b=document.createElement('button');b.type='button';b.className='stepper';b.textContent=direction<0?'−':'+';b.setAttribute('aria-label',`${direction<0?'減少':'增加'}${label?.textContent||'數字'}`);b.addEventListener('click',()=>{const step=Number(el.step)||1;el.value=Math.min(Number(el.max),Math.max(Number(el.min),(Number(el.value)||0)+direction*step));update(el.id);});wrap.append(b);if(direction<0)wrap.append(el);}}
for(const b of document.querySelectorAll('[data-who]'))b.addEventListener('click',()=>{if($('who').value===b.dataset.who)return;$('who').value=b.dataset.who;for(const x of document.querySelectorAll('[data-who]')){x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b));}$('who').dispatchEvent(new Event('change'));});
$('who').addEventListener('change',()=>{drafts.set(previousWho,{their:$('their').value,milestone:$('milestone').value,duration,period:frequencyPeriod,count:$('frequency-count').value});const who=$('who').value,v=defaults[who],saved=drafts.get(who);$('their').value=saved?.their??v[0];$('milestone').value=saved?.milestone??(who==='partner'?Math.min(v[1],Number($('age').value)):v[1]);duration=saved?.duration??2;frequencyPeriod=saved?.period??(who==='partner'?'week':'month');$('frequency-count').max=periodSettings[frequencyPeriod].max;$('frequency-count').value=saved?.count??1;for(const b of $('duration').querySelectorAll('button')){const active=Number(b.dataset.value)===duration;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active));}$('extra').value=0;$('extraHours').value=0;previousWho=who;update('who');});

$('show-result').addEventListener('click',()=>{update();if($('error').textContent){$('error').scrollIntoView({block:'center'});return;}$('form-panel').hidden=true;$('form-intro').hidden=true;$('result-panel').hidden=true;$('time-loading').hidden=false;window.scrollTo({top:0,behavior:'instant'});clearTimeout(estimateTimer);estimateTimer=setTimeout(()=>toggleResult(true),3500);});$('reset').addEventListener('click',()=>toggleResult(false));$('cancel-estimate').addEventListener('click',()=>toggleResult(false));
$('share-experience').addEventListener('click',async()=>{const button=$('share-experience');button.disabled=true;try{const status=await window.ExhibitionInvitation.share();if(status==='fallback'){$('time-invitation-message').textContent=window.ExhibitionInvitation.text();$('time-share-box').hidden=false;$('time-share-status').textContent='';}}finally{button.disabled=false;}});
$('copy-invitation').addEventListener('click',async()=>{try{await window.ExhibitionInvitation.copy();$('time-share-status').textContent='已複製邀請訊息。';}catch(error){$('time-share-status').textContent='可以長按上面嘅邀請訊息複製。';}});
update();
